26	
27	    var body: some View {
28	        TimelineView(timelineContext: timelineContext)
29	            .overlay(alignment: .bottomTrailing) {
30	                TimelineScrollToBottomButton(isVisible: isAtBottomAndLive) {
31	                    timelineContext.send(viewAction: .scrollToBottom)
32	                }
33	                .accessibilityIdentifier(A11yIdentifiers.roomScreen.scrollToBottom)
34	            }
35	            .background(Color.compound.bgCanvasDefault.ignoresSafeArea())
36	            .topBanners([
37	                TopBannerItem(pinnedItemsBanner, isVisible: context.viewState.shouldShowPinnedEventsBanner && !isVoiceOverEnabled),
38	                // This can overlay on top of the pinnedItemsBanner
39	                TopBannerItem(knockRequestsBanner, isVisible: context.viewState.shouldSeeKnockRequests)
40	            ], footer: dateBadge)
41	            .safeAreaInset(edge: .top) {
42	                // When VoiceOver is enabled, the table view isn't reversed and the scroll gestures
43	                // don't trigger meaning the banner never hides itself and so the .overlay layout
44	                // above permanently obscures the top of the timeline. So whenever VoiceOver is
45	                // enabled we use a safe area inset to vertically stack it above the timeline.
46	                if context.viewState.shouldShowPinnedEventsBanner, isVoiceOverEnabled {
