70	            .toolbarBackground(.visible, for: .navigationBar) // Fix the toolbar's background.
71	            .overlay { loadingIndicator }
72	            .alert(item: $context.alertInfo)
73	            .timelineMediaPreview(viewModel: $context.mediaPreviewViewModel)
74	            .track(screen: .Room)
