118	        if context.viewState.hasSuccessor {
119	            tombstonedDialogue
120	        } else if context.viewState.canSendMessage, !ProcessInfo.isRunningAccessibilityTests {
121	            // We are not sure why but when wrapped in the room screen the composer toolbar breaks the accessibility tests
