14	enum AppRoute: Hashable {
15	    /// An account provisioning link generated externally.
16	    case accountProvisioningLink(AccountProvisioningParameters)
17	    
18	    /// The app's home screen.
19	    case roomList
20	    /// A room, shown as the root of the stack (popping any child rooms).
21	    case room(roomID: String, via: [String])
22	    /// The same as ``room`` but using a room alias.
23	    case roomAlias(String)
24	    /// A room, pushed as a child of any existing rooms on the stack.
25	    case childRoom(roomID: String, via: [String])
26	    /// The same as ``childRoom`` but using a room alias.
27	    case childRoomAlias(String)
28	    /// The information about a particular room.
29	    case roomDetails(roomID: String)
30	    /// The profile of a member within the current room.
31	    case roomMemberDetails(userID: String)
32	    /// An event within a room, shown as the root of the stack (popping any child rooms).
33	    case event(eventID: String, roomID: String, via: [String])
34	    /// The same as ``event`` but using a room alias.
35	    case eventOnRoomAlias(eventID: String, alias: String)
36	    /// An event within a room, either within the last child on the stack or pushing a new child if needed.
37	    case childEvent(eventID: String, roomID: String, via: [String])
38	    /// The same as ``childEvent`` but using a room alias.
39	    case childEventOnRoomAlias(eventID: String, alias: String)
40	    /// The profile of a matrix user (outside of a room).
41	    case userProfile(userID: String)
42	    /// An Element Call running in a particular room
43	    case call(roomID: String, isVoiceCall: Bool)
44	    /// An Element Call link generated outside of a chat room.
45	    case genericCallLink(url: URL)
46	    /// The settings screen.
47	    case settings
48	    /// The setting screen for key backup.
49	    case chatBackupSettings
50	    /// An external share request e.g. from the ShareExtension
51	    case share(ShareExtensionPayload)
52	    /// The change roles screen of a room with the transfer ownership setting
53	    case transferOwnership(roomID: String)
54	    /// A thread within a room, only to be used to handle tap on notification for threaded events.
55	    case thread(roomID: String, threadRootEventID: String, focusEventID: String?)
56	    
57	    /// Whether or not the route should be handled by the authentication flow.
58	    var isAuthenticationRoute: Bool {
59	        switch self {
60	        case .accountProvisioningLink: true
61	        default: false
62	        }
63	    }
64	}
