66	/// The parameters parsed out of a provisioning link that can be applied to the authentication flow for a streamlined onboarding experience.
67	struct AccountProvisioningParameters: Hashable {
68	    let accountProvider: String
69	    let loginHint: String?
70	    
71	    enum CodingKeys: String, CodingKey {
72	        case accountProvider = "account_provider"
73	        case loginHint = "login_hint"
74	    }
