77	struct AppRouteURLParser {
78	    let urlParsers: [URLParser]
79	    
80	    init(appSettings: AppSettings) {
81	        urlParsers = [
82	            AppGroupURLParser(),
83	            MatrixPermalinkParser(),
84	            ElementWebURLParser(domains: appSettings.elementWebHosts),
85	            AccountProvisioningURLParser(domain: appSettings.accountProvisioningHost),
86	            ElementCallURLParser()
87	        ]
88	    }
89	    
90	    func route(from url: URL) -> AppRoute? {
91	        for parser in urlParsers {
92	            if let appRoute = parser.route(from: url) {
93	                return appRoute
94	            }
95	        }
96	        
97	        return nil
98	    }
99	}
