101	// MARK: - URL Parsers
102	
103	/// Represents a type that can parse a `URL` into an `AppRoute`.
104	///
105	/// The following Universal Links are missing parsers.
106	/// - mobile.element.io
107	protocol URLParser {
108	    func route(from url: URL) -> AppRoute?
109	}
110	
111	/// The parser for routes that come from app extensions such as the Share Extension.
112	private struct AppGroupURLParser: URLParser {
113	    func route(from url: URL) -> AppRoute? {
114	        guard let scheme = url.scheme,
115	              scheme == InfoPlistReader.app.appScheme,
116	              url.pathComponents.last == ShareExtensionConstants.urlPath else {
117	            return nil
118	        }
119	        
120	        guard let query = url.query(percentEncoded: false),
121	              let queryData = query.data(using: .utf8) else {
122	            MXLog.error("Failed processing share parameters")
123	            return nil
124	        }
125	        
126	        do {
127	            let payload = try JSONDecoder().decode(ShareExtensionPayload.self, from: queryData)
128	            return .share(payload)
129	        } catch {
130	            MXLog.error("Failed decoding share payload with error: \(error)")
131	            return nil
132	        }
133	    }
134	}
