136	/// The parser for Element Call links. This always returns a `.genericCallLink`.
137	private struct ElementCallURLParser: URLParser {
138	    private let knownHosts = ["call.element.io"]
139	    private let customSchemeURLQueryParameterName = "url"
140	    
141	    func route(from url: URL) -> AppRoute? {
142	        // Element Call not supported, WebRTC not available
143	        // https://github.com/element-hq/element-x-ios/issues/1794
144	        if ProcessInfo.processInfo.isiOSAppOnMac {
145	            return nil
146	        }
147	        
148	        // First try processing URLs with custom schemes
149	        if let scheme = url.scheme,
150	           scheme == InfoPlistReader.app.elementCallScheme {
151	            guard let components = URLComponents(url: url, resolvingAgainstBaseURL: false) else {
152	                return nil
153	            }
154	            
155	            guard let encodedURLString = components.queryItems?.first(where: { $0.name == customSchemeURLQueryParameterName })?.value,
156	                  let callURL = URL(string: encodedURLString),
157	                  callURL.scheme == "https" // Don't allow URLs from potentially unsafe domains
158	            else {
159	                MXLog.error("Invalid custom scheme call parameters: \(url)")
160	                return nil
161	            }
162	            
163	            return .genericCallLink(url: callURL)
164	        }
165	        
166	        // Otherwise try to interpret it as an universal link
167	        guard let host = url.host, knownHosts.contains(host) else {
168	            return nil
169	        }
170	        
171	        return .genericCallLink(url: url)
172	    }
173	}
