175	private struct MatrixPermalinkParser: URLParser {
176	    func route(from url: URL) -> AppRoute? {
177	        guard let entity = parseMatrixEntityFrom(uri: url.absoluteString) else { return nil }
178	        
179	        switch entity.id {
180	        case .room(let id):
181	            return .room(roomID: id, via: entity.via)
182	        case .roomAlias(let alias):
183	            return .roomAlias(alias)
184	        case .user(let id):
185	            return .userProfile(userID: id)
186	        case .eventOnRoomId(let roomID, let eventID):
187	            return .event(eventID: eventID, roomID: roomID, via: entity.via)
188	        case .eventOnRoomAlias(let alias, let eventID):
189	            return .eventOnRoomAlias(eventID: eventID, alias: alias)
190	        }
191	    }
192	}
193	
194	private struct ElementWebURLParser: URLParser {
195	    let domains: [String]
196	    let paths = ["room", "user"]
197	    
198	    private let permalinkParser = MatrixPermalinkParser()
199	    
200	    func route(from url: URL) -> AppRoute? {
201	        guard let matrixToURL = buildMatrixToURL(from: url) else { return nil }
202	        return permalinkParser.route(from: matrixToURL)
203	    }
204	    
205	    private func buildMatrixToURL(from url: URL) -> URL? {
206	        guard var components = URLComponents(url: url, resolvingAgainstBaseURL: false) else {
207	            return url
208	        }
209	        
210	        for domain in domains where domain == url.host {
211	            components.host = "matrix.to"
212	            for path in paths {
213	                components.fragment?.replace("/\(path)", with: "")
214	            }
215	            
216	            guard let matrixToURL = components.url else { continue }
217	            return matrixToURL
218	        }
219	        
220	        return url
221	    }
222	}
223	
224	/// The parser for user provisioning links.
225	private struct AccountProvisioningURLParser: URLParser {
226	    let domain: String
227	    
228	    func route(from url: URL) -> AppRoute? {
229	        guard url.host() == domain else { return nil }
230	        
231	        guard let components = URLComponents(url: url, resolvingAgainstBaseURL: false),
232	              let serverName = components.queryItems?.first(where: { $0.name == AccountProvisioningParameters.CodingKeys.accountProvider.rawValue })?.value else {
233	            return nil
234	        }
235	        
236	        let loginHint = components.queryItems?.first { $0.name == AccountProvisioningParameters.CodingKeys.loginHint.rawValue }?.value
237	        
238	        return .accountProvisioningLink(.init(accountProvider: serverName, loginHint: loginHint))
239	    }
240	}
