14	enum RoomFlowCoordinatorAction: Equatable {
15	    case presentCallScreen(roomProxy: JoinedRoomProxyProtocol)
16	    case verifyUser(userID: String)
17	    /// The requested room was actually a space. The room flow has been dismissed
18	    /// and a space flow should be started to continue.
19	    case continueWithSpaceFlow(SpaceRoomListProxyProtocol)
20	    case finished
21	    
22	    static func == (lhs: RoomFlowCoordinatorAction, rhs: RoomFlowCoordinatorAction) -> Bool {
23	        switch (lhs, rhs) {
24	        case (.presentCallScreen(let lhsRoomProxy), .presentCallScreen(let rhsRoomProxy)):
25	            lhsRoomProxy.id == rhsRoomProxy.id
26	        case (.finished, .finished):
27	            true
28	        default:
29	            false
30	        }
31	    }
32	}
