34	/// A value that represents where the room flow will be started.
35	enum RoomFlowCoordinatorEntryPoint: Hashable {
36	    /// The flow will start by showing the room directly.
37	    case room
38	    /// The flow will start by showing the room, focussing on the supplied event ID.
39	    case eventID(String)
40	    /// The flow will start by showing a thread timeline, can only be triggered by notification taps,
41	    /// which means it can never be a used for child flows.
42	    case thread(rootEventID: String, focusEventID: String?)
43	    /// The flow will start by showing the room's details.
44	    case roomDetails
45	    /// An external media share request
46	    case share(ShareExtensionPayload)
47	    /// The flow to change the the owner of the room
48	    case transferOwnership
49	    
50	    var isEventID: Bool {
51	        guard case .eventID = self else { return false }
52	        return true
53	    }
54	}
