221	    private func handleChildEventRoute(eventID: String, roomID: String, via: [String], animated: Bool) {
222	        if case .membersFlow = stateMachine.state, let membersFlowCoordinator {
223	            membersFlowCoordinator.handleAppRoute(.childEvent(eventID: eventID, roomID: roomID, via: via), animated: animated)
224	        } else if case .presentingChild = stateMachine.state, let childRoomFlowCoordinator {
225	            childRoomFlowCoordinator.handleAppRoute(.childEvent(eventID: eventID, roomID: roomID, via: via), animated: animated)
226	        } else if roomID != roomProxy.id {
227	            stateMachine.tryEvent(.startChildFlow(roomID: roomID, via: via, entryPoint: .eventID(eventID)), userInfo: EventUserInfo(animated: animated))
228	        } else {
229	            showLoadingIndicator(delay: .seconds(0.5))
230	            Task {
231	                defer { hideLoadingIndicator() }
232	                switch await roomProxy.loadOrFetchEventDetails(for: eventID) {
233	                case .success(let event):
234	                    if flowParameters.appSettings.threadsEnabled, let threadRootEventID = event.threadRootEventId() {
235	                        if case .thread(threadRootEventID: threadRootEventID, _) = stateMachine.state, let threadCoordinator = childThreadScreenCoordinators.last {
236	                            threadCoordinator.focusOnEvent(eventID: eventID)
237	                        } else {
238	                            // If we are showing the room timeline, we want to focus the thread root.
239	                            if childThreadScreenCoordinators.isEmpty {
240	                                roomScreenCoordinator?.focusOnEvent(.init(eventID: threadRootEventID, shouldSetPin: false))
241	                            }
242	                            stateMachine.tryEvent(.presentThread(threadRootEventID: threadRootEventID, focusEventID: eventID))
243	                        }
244	                    } else if !childThreadScreenCoordinators.isEmpty {
245	                        // If we are showing a child thread and we are navigating to a non threaded event
246	                        // of the same room, we want to push the room on top of the thread.
247	                        stateMachine.tryEvent(.startChildFlow(roomID: roomID, via: via, entryPoint: .eventID(eventID)), userInfo: EventUserInfo(animated: animated))
248	                    } else {
249	                        roomScreenCoordinator?.focusOnEvent(.init(eventID: eventID, shouldSetPin: false))
250	                    }
251	                case .failure:
252	                    showErrorIndicator()
253	                }
254	            }
255	        }
256	    }
