399	    /// Scrolls to the item with the corresponding event ID if loaded in the timeline.
400	    private func scrollToItem(eventID: String, animated: Bool) {
401	        DispatchQueue.main.async { [weak self] in // Fixes #2805
402	            guard let self else { return }
403	            if let kvPair = timelineItemsDictionary.first(where: { $0.value.identifier.eventID == eventID }),
404	               let indexPath = dataSource?.indexPath(for: kvPair.key) {
405	                // Scrolling to the middle created a small bump in the timeline
406	                // Using top, which is bottom in the reversed timeline helps with rendering
407	                // in full long messages and images
408	                tableView.scrollToRow(at: indexPath, at: .top, animated: animated)
409	                coordinator.send(viewAction: .scrolledToFocussedItem)
410	                // Ensure VoiceOver focus happens after the scroll animation (if any)
411	                DispatchQueue.main.asyncAfter(deadline: .now() + (animated ? 0.5 : 0.0)) {
412	                    if let cell = self.tableView.cellForRow(at: indexPath) {
413	                        UIAccessibility.post(notification: .layoutChanged, argument: cell)
414	                    }
415	                }
416	            }
417	        }
418	    }
