420	    /// Checks whether or not pagination is needed in either direction and requests one if so.
421	    ///
422	    /// **Note:** Prefer not to call this directly, instead using ``paginatePublisher`` to throttle requests.
423	    private func paginateIfNeeded() {
424	        guard !hasPendingItems else { return }
425	        
426	        if paginationState.backward == .idle,
427	           tableView.contentOffset.y > tableView.contentSize.height - tableView.visibleSize.height * 2.0 {
428	            coordinator.send(viewAction: .paginateBackwards)
429	        }
430	        if !isLive,
431	           paginationState.forward == .idle,
432	           tableView.contentOffset.y < tableView.visibleSize.height {
433	            coordinator.send(viewAction: .paginateForwards)
434	        }
435	    }
