437	    private func sendLastVisibleItemReadReceipt() {
438	        // Find the last visible timeline item and send a read receipt for it
439	        guard let visibleIndexPaths = tableView.indexPathsForVisibleRows else {
440	            return
441	        }
442	        
443	        // These are already in reverse order because the table view is flipped
444	        for indexPath in visibleIndexPaths {
445	            if let visibleItemUniqueID = dataSource?.itemIdentifier(for: indexPath),
446	               let visibleItemID = timelineItemsDictionary[visibleItemUniqueID]?.identifier {
447	                coordinator.send(viewAction: .sendReadReceiptIfNeeded(visibleItemID))
448	                return
449	            }
450	        }
451	    }
