457	    func scrollViewDidScroll(_ scrollView: UIScrollView) {
458	        paginatePublisher.send(())
459	        
460	        // Dispatch to fix runtime warning about making changes during a view update.
461	        DispatchQueue.main.async { [weak self] in
462	            guard let self else { return }
463	            
464	            let isScrolledToBottom = scrollView.contentOffset.y <= 0
465	            
466	            // Only update the binding on changes to avoid needlessly recomputing the hierarchy when scrolling.
467	            if self.isScrolledToBottom != isScrolledToBottom {
468	                self.isScrolledToBottom = isScrolledToBottom
469	            }
470	            
471	            if !isScrolledToBottom {
472	                updateFloatingDate()
473	            }
474	        }
475	
476	        // We never want the table view to be fully at the bottom to allow the status bar tap to work properly
477	        if scrollView.contentOffset.y == 0 {
478	            scrollView.contentOffset.y = -1
479	        }
480	        
481	        let velocity = scrollView.panGestureRecognizer.velocity(in: scrollView.superview).y
482	        if velocity > scrollVelocityThreshold {
483	            scrollDirectionPublisher.send(.top)
484	        } else if velocity < -scrollVelocityThreshold {
485	            scrollDirectionPublisher.send(.bottom)
486	        }
487	    }
